-- RAVINE Platform Domain Foundation v1
-- Staged only. This migration is intentionally NOT applied to the current Supabase production project.
-- It converts the Charter/Next domain model into explicit, auditable objects while keeping open provider decisions replaceable.

create table if not exists public.ravine_next_identity_profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, bio text, avatar_url text, language text check (language in ('ar','en')), appearance text check (appearance in ('dark','light','system')) default 'dark', reduced_motion boolean not null default false, ai_memory_enabled boolean not null default true, personalization_enabled boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.ravine_next_creator_identities (id bigint generated by default as identity primary key, owner_user_id uuid not null references auth.users(id) on delete cascade, name text not null, handle text not null unique, avatar_url text, cover_url text, bio text, specialties text[] not null default '{}', status text not null default 'creator' check (status in ('creator','verified_creator','select_creator')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists ravine_next_creator_owner_idx on public.ravine_next_creator_identities(owner_user_id);
create table if not exists public.ravine_next_identity_switch_events (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, creator_identity_id bigint references public.ravine_next_creator_identities(id) on delete set null, mode text not null check (mode in ('personal','creator','team')), created_at timestamptz not null default now());
create table if not exists public.ravine_next_works (id bigint generated by default as identity primary key, creator_identity_id bigint references public.ravine_next_creator_identities(id) on delete set null, title text not null, description text, work_type text not null check (work_type in ('film','short','documentary','photography','motion_vfx','podcast','audio','music','series_episode','gaming','other')), status text not null default 'draft' check (status in ('draft','processing','published','unlisted','archived')), visibility text not null default 'public' check (visibility in ('public','followers','members','tier','invite_only','private')), discovery_enabled boolean not null default true, poster_url text, artwork_url text, primary_media_url text, provenance_status text check (provenance_status in ('human_created','ai_assisted','ai_generated','ai_edited','synthetic_manipulated','unavailable')), published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists ravine_next_work_creator_idx on public.ravine_next_works(creator_identity_id, created_at desc);
create index if not exists ravine_next_work_discovery_idx on public.ravine_next_works(status, visibility, discovery_enabled, published_at desc);
create table if not exists public.ravine_next_work_credits (id bigint generated by default as identity primary key, work_id bigint not null references public.ravine_next_works(id) on delete cascade, creator_identity_id bigint references public.ravine_next_creator_identities(id) on delete set null, role_label text not null, display_name text not null, sort_order integer not null default 0, created_at timestamptz not null default now());
create table if not exists public.ravine_next_collections (id bigint generated by default as identity primary key, owner_user_id uuid not null references auth.users(id) on delete cascade, title text not null, description text, visibility text not null default 'private' check (visibility in ('private','team','members','public')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.ravine_next_collection_items (collection_id bigint not null references public.ravine_next_collections(id) on delete cascade, work_id bigint references public.ravine_next_works(id) on delete cascade, creator_identity_id bigint references public.ravine_next_creator_identities(id) on delete cascade, sort_order integer not null default 0, primary key (collection_id, work_id, creator_identity_id));
create table if not exists public.ravine_next_follows (follower_user_id uuid not null references auth.users(id) on delete cascade, creator_identity_id bigint not null references public.ravine_next_creator_identities(id) on delete cascade, created_at timestamptz not null default now(), primary key (follower_user_id, creator_identity_id));
create table if not exists public.ravine_next_communities (id uuid primary key default gen_random_uuid(), creator_identity_id bigint references public.ravine_next_creator_identities(id) on delete cascade, parent_id uuid references public.ravine_next_communities(id) on delete set null, slug text not null unique, community_type text not null check (community_type in ('platform','topic','creator','user_created','member_only','circle','project','gaming','local')), name_en text not null, name_ar text not null, description_en text, description_ar text, visibility text not null default 'public' check (visibility in ('public','followers','members','invite_only','private')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.ravine_next_community_members (community_id uuid not null references public.ravine_next_communities(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null default 'member' check (role in ('owner','admin','moderator','member','visitor')), status text not null default 'active' check (status in ('active','pending','banned')), joined_at timestamptz not null default now(), primary key (community_id, user_id));
create table if not exists public.ravine_next_broadcasts (id uuid primary key default gen_random_uuid(), creator_identity_id bigint not null references public.ravine_next_creator_identities(id) on delete cascade, author_user_id uuid not null references auth.users(id) on delete cascade, post_type text not null check (post_type in ('text','image','short_video','voice','link','poll','project','premiere','bts','live','member_update')), body text, visibility text not null default 'public' check (visibility in ('public','followers','members','tier','invite_only')), related_work_id bigint references public.ravine_next_works(id) on delete set null, created_at timestamptz not null default now());
create table if not exists public.ravine_next_membership_tiers (id uuid primary key default gen_random_uuid(), creator_identity_id bigint not null references public.ravine_next_creator_identities(id) on delete cascade, name text not null, description text, sort_order integer not null default 0, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.ravine_next_memberships (user_id uuid not null references auth.users(id) on delete cascade, tier_id uuid not null references public.ravine_next_membership_tiers(id) on delete cascade, status text not null default 'active' check (status in ('active','paused','cancelled','expired')), started_at timestamptz not null default now(), ended_at timestamptz, primary key (user_id, tier_id));
create table if not exists public.ravine_next_live_sessions (id uuid primary key default gen_random_uuid(), creator_identity_id bigint references public.ravine_next_creator_identities(id) on delete cascade, title text not null, mode text not null check (mode in ('solo','co_live','guest','panel','workshop','qa','premiere','watch_party','gaming','audio','camera_off','bts','sessions')), provider_key text, status text not null default 'scheduled' check (status in ('scheduled','live','recorded','edited','published','cancelled')), starts_at timestamptz, ended_at timestamptz, related_work_id bigint references public.ravine_next_works(id) on delete set null, created_at timestamptz not null default now());
create table if not exists public.ravine_next_live_participants (session_id uuid not null references public.ravine_next_live_sessions(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check (role in ('host','co_host','guest','speaker','audience','producer')), mode text check (mode in ('video','audio','camera_off')), status text not null default 'active' check (status in ('requested','queued','active','removed','left')), created_at timestamptz not null default now(), primary key (session_id, user_id));
create table if not exists public.ravine_next_ratings (id uuid primary key default gen_random_uuid(), work_id bigint not null references public.ravine_next_works(id) on delete cascade, rater_user_id uuid not null references auth.users(id) on delete cascade, source_type text not null check (source_type in ('audience','creator','editorial')), score numeric(4,2), dimensions jsonb not null default '{}', review_text text, created_at timestamptz not null default now(), unique(work_id, rater_user_id));
create table if not exists public.ravine_next_reports (id uuid primary key default gen_random_uuid(), reporter_user_id uuid not null references auth.users(id) on delete cascade, entity_type text not null check (entity_type in ('work','creator','comment','community','live','broadcast')), entity_id text not null, reason text not null, details text, status text not null default 'open' check (status in ('open','reviewing','resolved','dismissed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.ravine_next_rights_claims (id uuid primary key default gen_random_uuid(), work_id bigint references public.ravine_next_works(id) on delete cascade, claimant_user_id uuid references auth.users(id) on delete cascade, claim_type text not null, evidence jsonb not null default '{}', status text not null default 'review' check (status in ('review','accepted','rejected','withdrawn')), created_at timestamptz not null default now());
create table if not exists public.ravine_next_opportunities (id uuid primary key default gen_random_uuid(), creator_identity_id bigint references public.ravine_next_creator_identities(id) on delete set null, title text not null, opportunity_type text not null, description text, status text not null default 'open' check (status in ('draft','open','closed','filled')), created_at timestamptz not null default now());
create table if not exists public.ravine_next_ai_audit_events (id bigint generated by default as identity primary key, actor_user_id uuid references auth.users(id) on delete set null, tool_key text, model_key text, model_version text, policy_version text, action_class text not null check (action_class in ('read','recommend','tool','sensitive')), decision text, confidence numeric(5,4), risk_score numeric(5,4), reason_codes text[] not null default '{}', human_override boolean not null default false, created_at timestamptz not null default now());

alter table public.ravine_next_identity_profiles enable row level security;
alter table public.ravine_next_creator_identities enable row level security;
alter table public.ravine_next_identity_switch_events enable row level security;
alter table public.ravine_next_works enable row level security;
alter table public.ravine_next_work_credits enable row level security;
alter table public.ravine_next_collections enable row level security;
alter table public.ravine_next_collection_items enable row level security;
alter table public.ravine_next_follows enable row level security;
alter table public.ravine_next_communities enable row level security;
alter table public.ravine_next_community_members enable row level security;
alter table public.ravine_next_broadcasts enable row level security;
alter table public.ravine_next_membership_tiers enable row level security;
alter table public.ravine_next_memberships enable row level security;
alter table public.ravine_next_live_sessions enable row level security;
alter table public.ravine_next_live_participants enable row level security;
alter table public.ravine_next_ratings enable row level security;
alter table public.ravine_next_reports enable row level security;
alter table public.ravine_next_rights_claims enable row level security;
alter table public.ravine_next_opportunities enable row level security;
alter table public.ravine_next_ai_audit_events enable row level security;

drop policy if exists ravine_next_work_public_read on public.ravine_next_works;
create policy ravine_next_work_public_read on public.ravine_next_works for select using (status = 'published' and visibility = 'public' and discovery_enabled = true);
drop policy if exists ravine_next_work_owner_insert on public.ravine_next_works;
create policy ravine_next_work_owner_insert on public.ravine_next_works for insert to authenticated with check (exists (select 1 from public.ravine_next_creator_identities c where c.id = creator_identity_id and c.owner_user_id = auth.uid()));
drop policy if exists ravine_next_work_owner_update on public.ravine_next_works;
create policy ravine_next_work_owner_update on public.ravine_next_works for update to authenticated using (exists (select 1 from public.ravine_next_creator_identities c where c.id = creator_identity_id and c.owner_user_id = auth.uid())) with check (exists (select 1 from public.ravine_next_creator_identities c where c.id = creator_identity_id and c.owner_user_id = auth.uid()));
drop policy if exists ravine_next_creator_public_read on public.ravine_next_creator_identities;
create policy ravine_next_creator_public_read on public.ravine_next_creator_identities for select using (true);
drop policy if exists ravine_next_profile_self on public.ravine_next_identity_profiles;
create policy ravine_next_profile_self on public.ravine_next_identity_profiles for all to authenticated using (id = auth.uid()) with check (id = auth.uid());
drop policy if exists ravine_next_follow_self on public.ravine_next_follows;
create policy ravine_next_follow_self on public.ravine_next_follows for all to authenticated using (follower_user_id = auth.uid()) with check (follower_user_id = auth.uid());
drop policy if exists ravine_next_collection_owner on public.ravine_next_collections;
create policy ravine_next_collection_owner on public.ravine_next_collections for all to authenticated using (owner_user_id = auth.uid()) with check (owner_user_id = auth.uid());
drop policy if exists ravine_next_membership_self on public.ravine_next_memberships;
create policy ravine_next_membership_self on public.ravine_next_memberships for select to authenticated using (user_id = auth.uid());
drop policy if exists ravine_next_rating_self on public.ravine_next_ratings;
create policy ravine_next_rating_self on public.ravine_next_ratings for all to authenticated using (rater_user_id = auth.uid()) with check (rater_user_id = auth.uid());
drop policy if exists ravine_next_report_self on public.ravine_next_reports;
create policy ravine_next_report_self on public.ravine_next_reports for insert to authenticated with check (reporter_user_id = auth.uid());

grant select on public.ravine_next_works to anon, authenticated;
grant insert, update on public.ravine_next_works to authenticated;
grant select on public.ravine_next_creator_identities to anon, authenticated;
grant select, insert, update on public.ravine_next_identity_profiles to authenticated;
grant select, insert, delete on public.ravine_next_follows to authenticated;
grant select, insert, update, delete on public.ravine_next_collections to authenticated;
grant select on public.ravine_next_memberships to authenticated;
grant select, insert, update on public.ravine_next_ratings to authenticated;
grant insert on public.ravine_next_reports to authenticated;
